// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-convert-multiple-images' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "<p>画像を1枚ずつ変換するのは、1枚の写真なら問題ありません。50枚のフォルダでは、午後の時間を食う面倒な作業になります。一括変換なら、フォルダ全体を1回の処理で終わらせられます。</p>\n<p>手順はシンプルです。フォルダをアップロードし、出力形式を1つ選び、画質を1回設定して、すべてが入った1つのZIPをダウンロードします。</p>\n<p>この記事では、各ステップを解説します。きれいで一貫したバッチのための、重要な設定も押さえます。</p>\n<h2 id=\"prepare-your-folder\">ステップ0：まずフォルダを準備する</h2>\n<p>始める前に、変換したい画像をすべて1つのフォルダに入れてください。フォルダが整理されていれば、1回のアップロードで済みます。ドライブの中を探し回る必要がありません。</p>\n<p>関係のないファイルを取り除きます。古いスクリーンショット、重複ファイル、無関係の写真は、バッチを遅くし、ZIPを散らかすだけです。</p>\n<p>問題のあるファイルを確認してください。拡張子が.jpgでも中身がWebPのファイルや、途中で止まったダウンロード画像は、変換中に失敗します。先に修正するか、取り除きましょう。</p>\n<p>原本は安全に保管してください。変換ツールが原本を変更することはありませんが、バッチ作業の前に別フォルダにバックアップを取るのがよい習慣です。</p>\n<h2 id=\"upload-the-batch\">ステップ1：バッチ全体をアップロードする</h2>\n<p><a href=\"/ja/ikkatsu-gazo-henkan/\">画像一括変換ツール</a>をブラウザで開いてください。パソコンでもスマホでも動作し、インストールは不要です。</p>\n<p>フォルダをアップロードエリアにドラッグするか、クリックして複数のファイルを選択します。ファイル選択画面では、数十ファイルを一度に選べます。</p>\n<p>各ファイルは、名前、寸法、サイズ付きのカードとして表示されます。リストをざっと確認し、抜けがなく、余分なものが混ざっていないことを確かめてください。</p>\n<p>1ファイルあたり25MBまで受け付けます。スマホ写真、カメラの写真、大きなスクリーンショットはたいてい収まるので、ほとんどのフォルダは準備なしでアップロードできます。</p>\n<h2 id=\"pick-the-target-format\">ステップ2：変換先の形式を選ぶ</h2>\n<p>バッチのほとんどが写真で、送り先が一般的な場合はJPGを選んでください。すべてのシステムがJPGを受け付け、ファイルは小さくて持ち運びやすいままです。</p>\n<p>バッチがWebサイト用ならWebPを選んでください。同じ画質でJPGより小さく、透過も保てるので、写真とロゴが混ざったバッチにも合います。</p>\n<p>バッチがグラフィック、アイコン、文字入りのスクリーンショットならPNGを選んでください。PNGは輪郭をシャープに保ち、透過もそのまま残りますが、ファイルは大きくなります。</p>\n<p>1つの形式がバッチ全体に適用されることを忘れないでください。2つの形式が必要なら、手作業で分けるのではなく、バッチを2回実行してください。</p>\n<h2 id=\"set-quality-once\">ステップ3：画質を1回だけ設定する</h2>\n<p>画質スライダーは、バッチ内のすべてのファイルに適用されます。JPGやWebPの出力では、写真が混ざったバッチは80〜85%が安全な既定値です。</p>\n<p>文字の多いスクリーンショットを含むバッチでは、85%のWebPを選びましょう。小さな文字を読みやすく保てます。JPGは文字をにじませがちです。</p>\n<p>印刷するバッチでは、画質を90%以上に上げてください。印刷では画面で隠れる欠点が見えます。余分なサイズは、それだけの価値があります。</p>\n<p>PNGを選ぶと、スライダーは表示されません。PNGは可逆形式なので、選べる画質はなく、すべてのファイルが画素を正確に保存します。</p>\n<h2 id=\"transparency-decisions\">ステップ4：透過について決める</h2>\n<p>変換先がJPGの場合は、透明部分のマット色を選んでください。ほとんどの用途には白が合い、特定のWebサイトの背景にはブランドカラーが合います。</p>\n<p>最初の変換のあと、ロゴのカードを確認して、塗りつぶし色の見た目を確かめてください。ロゴの後ろに黒い四角が見えたら、塗りつぶし色が間違っていたことになり、変更できます。</p>\n<p>変換先がPNGやWebPの場合は、このステップは不要です。どちらの形式も透過を保つので、ロゴやステッカーは塗りつぶしなしで透けたまま残ります。</p>\n<p>混ざったバッチでは、ここで少し考える必要があります。同じJPGバッチのロゴと写真は塗りつぶし色を共有します。ただし塗りつぶしは透明部分だけに影響するので、写真は変わりません。</p>\n<h2 id=\"convert-and-watch\">ステップ5：変換して進捗を見る</h2>\n<p>変換ボタンをクリックして、カードが変わっていくのを見てください。各ファイルは独立して変換されるので、盲目的に待つのではなく、ファイルごとに進捗が分かります。</p>\n<p>大きなバッチは少し時間がかかります。すべてのファイルが端末でデコードと再エンコードされるからです。50枚の写真のバッチでも、たいてい1〜2分で終わります。</p>\n<p>バッチの実行中は、エラー表示に注意してください。壊れたファイルが1つあっても警告が出るだけで、残りのファイルは止まらずに完了します。</p>\n<p>バッチの実行中にファイルを追加することもできます。新しいファイルはキューに入り、残りのファイルと同じ設定で変換されます。</p>\n<h2 id=\"review-each-card\">ステップ6：結果をカードごとに確認する</h2>\n<p>変換後の各カードには、新しいファイルサイズが古いサイズと並んで表示されます。ざっと見るだけで、バッチで実際に容量が節約できたかが分かります。</p>\n<p>カードの比較ボタンをクリックして、変換前後を並べて確認してください。顔、文字、輪郭は、低画質の影響が最初に出る場所です。</p>\n<p>最後のバッチ概要にも注意してください。元のサイズ合計と変換後のサイズ合計が表示され、全体の節約量が1つの数字で分かります。</p>\n<p>小さくなるはずが合計が大きくなった場合、そのバッチには形式が間違っていました。PNGからWebPやJPGに切り替えて、もう一度変換してください。</p>\n<h2 id=\"download-as-zip\">ステップ7：すべてを1つのZIPでダウンロードする</h2>\n<p>まとめてダウンロードボタンをクリックして、バッチ全体を1つのZIPにまとめます。ZIPの名前で変換先の形式が分かるので、中身がすぐに分かります。</p>\n<p>原本の上にではなく、新しいフォルダに解凍してください。別のフォルダにすれば、変換後のファイルが整理され、誤った上書きを防げます。</p>\n<p>ファイル名の接尾辞を設定した場合は、すべての出力に付きます。-webpのような接尾辞があれば、変換後のファイルを原本と見分けやすくなります。</p>\n<p>使う前に、ZIPから数ファイルを確認してください。写真1枚とロゴ1枚を開き、見た目が正しく、形式が希望どおりか確かめます。</p>\n<ol>\n<li>変換する画像をすべて入れたフォルダを1つ準備する。</li>\n<li>フォルダを画像一括変換ツールにアップロードする。</li>\n<li>出力形式を1つ選び、画質を1回だけ設定する。</li>\n<li>変換してバッチ概要を確認し、ZIPをダウンロードする。</li>\n</ol>\n<h2 id=\"fixing-failed-files\">失敗したファイルを修正する</h2>\n<p>失敗したファイルには、カードにエラーの表示が出ます。メッセージを読んでください。対応していないファイルや壊れたファイルなど、問題が書かれていることが多いです。</p>\n<p>失敗したファイルをリストから取り除き、残りを変換してください。問題のあるファイルは別に扱えば、バッチ全体を止めずに済みます。</p>\n<p>何度も失敗するファイルは、本当の形式を確認してください。写真ビューアで開くか、プロパティを確認すれば、拡張子が間違っていることが分かります。</p>\n<p>頑固なファイルは、汎用の<a href=\"/ja/gazou-henkan/\">画像変換ツール</a>で1枚ずつ変換してください。1つのファイルは、50枚のバッチよりトラブルシューティングが簡単です。</p>\n<h2 id=\"converting-again-to-another-format\">同じバッチを別の形式に変換する</h2>\n<p>2つ目の版を作るために、再アップロードは不要です。最初の変換が終わったら、出力形式を変更してもう一度変換してください。</p>\n<p>原本は実行の合間もキューに残っているので、1回のアップロードでJPGバッチとWebPバッチの両方が作れます。形式を切り替える前に、それぞれのZIPをダウンロードしてください。</p>\n<p>2つのバッチを区別するために、ファイル名の接尾辞を使ってください。1回目は-jpg、2回目は-webpという接尾辞を付ければ、出力が整理されたままになります。</p>\n<p>この2形式の作業方法は、Webサイトでは一般的です。JPGは古いシステム向け、WebPは最近のブラウザ向けで、どちらも同じ元フォルダから作られます。</p>\n<h2 id=\"mobile-batch-tips\">スマホでのバッチのコツ</h2>\n<p>バッチ変換はスマホのブラウザでも動作しますが、遅く、画面も小さいです。スマホのバッチは12ファイル以下に抑えてください。</p>\n<p>ギャラリーから複数の写真を一度に選択してください。アップロードエリアは複数選択に対応しているので、写真を1枚ずつ追加する必要はありません。</p>\n<p>ダウンロードしたファイルは、ZIPとしてスマホのダウンロードフォルダに入ります。スマホによっては、解凍にファイルマネージャーアプリが必要になる場合があります。</p>\n<p>大きなフォルダはパソコンを使ってください。大きな画面と速いプロセッサーがあれば、100ファイルのバッチもはるかに快適です。</p>\n<h2 id=\"keeping-originals-safe\">原本を安全に保つ</h2>\n<p>変換ツールが原本を変更することは決してありません。原本を読み取り、新しいファイルを作り、元ファイルはそのまま残します。</p>\n<p>それでも、大きなバッチの前に、元フォルダのバックアップを取ってください。あとの手順で1つでもミスをすれば、たとえば原本の上に解凍してしまうなど、トラブルの原因になります。</p>\n<p>衝突を防ぐために、ファイル名の接尾辞を使ってください。変換後のファイルに-convertedのようなタグが付けば、誤って原本を上書きすることはありません。</p>\n<p>原本と変換後のコピーは、別フォルダに保存してください。明確な分離が、あとで混乱を避ける最もシンプルな方法です。</p>\n<h2 id=\"sorting-before-upload\">アップロード前の仕分け</h2>\n<p>アップロード前にざっと仕分けすれば、あとの時間が節約できます。写真、ロゴ、スクリーンショットを種類ごとに分け、それぞれが正しい設定のバッチになるようにします。</p>\n<p>写真は80〜85%のJPGかWebPが向いています。ロゴは透過を保ったPNGかWebPが向いています。文字入りのスクリーンショットは85%のWebPが向いています。</p>\n<p>仕分けには数分しかかからず、やり直しを防げます。混ざったバッチは、誰にもぴったり合わない妥協した設定を強いますが、仕分けたバッチはそれぞれ最適な設定を得られます。</p>\n<p>仕分けのときに、重複ファイルや不要なファイルを削除してください。余分なファイルは変換時間を食い、ZIPを散らかすので、アップロード前のざっとした選別は手間に見合います。</p>\n<p>仕分けたグループは、photos-to-webpやlogos-to-webpのように分かりやすい名前の別フォルダに入れてください。フォルダが、最初から最後までバッチを整理してくれます。</p>\n<h2 id=\"converting-trip-photos\">旅行写真を変換する</h2>\n<p>旅行写真は、典型的な一括作業です。iPhoneのHEICファイルが何百枚もあり、家族と共有したり、どこかにアップロードしたりする前に、JPGにする必要があります。</p>\n<p>まず写真を仕分けし、ぼやけた写真や重複を削除してください。300枚の旅行アルバムでも、残す価値があるのは50枚ほどです。その50枚だけを変換すれば、本当に時間が節約できます。</p>\n<p>残す写真は、90%のJPGに変換してください。写真が最もよく見え、ファイルはどこでも開け、アルバムは誰とでも共有できる状態になります。</p>\n<p>Webサイトやブログに載せる写真は、代わりにWebPに変換してください。ファイルは3分の1小さくなり、ページの表示が速くなり、画像は同じに見えます。</p>\n<p>変換後は、HEICの原本をアーカイブフォルダに残してください。最も画質のよいコピーであり、別の形式が必要になったらいつでも変換し直せます。</p>\n<h2 id=\"converting-work-documents\">仕事の書類を一括変換する</h2>\n<p>仕事の書類は、形式の混ざったスキャンのフォルダとして届くことがよくあります。すべてを1つの形式に変換すれば、書類一式が一貫して整理しやすくなります。</p>\n<p>読みやすさを保たなければならないスキャンは、PNGに変換してください。文字は編集や再保存を通してもシャープに残り、契約書やフォームではこれが重要です。</p>\n<p>小さく保たなければならないスキャンは、85%のJPGに変換してください。ファイルは大幅に小さくなり、文字もその設定では読みやすいままです。</p>\n<p>変換後のファイルには、書類と日付で名前を付けましょう。contract-2026-11.jpgのような名前なら、同僚は10個の候補を開かずに正しいファイルを見つけられます。</p>\n<p>変換した書類は、原本と同じフォルダ構成で共有ドライブに保存してください。構成をそろえれば、アーカイブは誰にとっても探しやすいままです。</p>\n<h2 id=\"reusing-settings\">繰り返しバッチの設定を再利用する</h2>\n<p>繰り返しバッチはよくあります。毎週同じ商品写真、毎月同じスクリーンショットです。設定を1回書き留めておけば、繰り返しのバッチはすべて同じになります。</p>\n<p>作業ごとに1行のメモを残してください。たとえば「WebP 85%、白マット」のようにです。その1行がレシピ全体で、誰でも推測なしに従えます。</p>\n<p>メモは、元ファイルの隣の作業フォルダに保存してください。次のバッチは、前回何がうまくいったかを思い出すのではなく、メモを読むことから始まります。</p>\n<p>設定が変わったら、すぐにメモを更新してください。古いメモは、メモがないより悪いです。違う見た目のバッチができてしまいます。</p>\n<p>メモは数か月ごとに見直してください。50枚に合った設定が500枚に合うとは限らず、小さな調整で大きな時間を節約できる場合があります。</p>\n<h2 id=\"converting-for-client-handover\">クライアントへの引き渡し用に変換する</h2>\n<p>クライアントへの引き渡しでは、クライアントが開ける形式の画像が必要です。JPGが最も安全な選択です。WebPファイルのフォルダは、クライアントの古いパソコンでは開けないかもしれませんが、JPGはどこでも開けます。</p>\n<p>画像は1つのバッチで変換し、すべて同じ画質にしてください。クライアントが一式を確認するとき、一貫性が重要です。画質が混ざると雑に見えます。</p>\n<p>変換後のファイルには、プロジェクトと日付で分かりやすく名前を付けてください。website-hero-nov-2026.jpgのような名前は内容を伝えますが、IMG_4821.jpgでは何も伝わりません。</p>\n<p>納品物には、形式と使用した設定を書いた短い説明を添えてください。1行のメモがあれば、クライアントはなぜ各画像が2つあるのか尋ねずに済みます。</p>\n<p>引き渡しのあとも、原本は自分のアーカイブに残してください。クライアントがあとで別の形式を求めた場合、原本があれば、ファイルを送り返してもらわずに変換し直せます。</p>\n<p>面倒なフォルダからすっきりしたZIPへの流れは以上です。</p>\n<p>全体の背景は<a href=\"/ja/blog/ikkatsu-gazou-henkan-gaido/\">画像の一括変換完全ガイド</a>、フォルダの作業方法と命名は<a href=\"/ja/blog/ikkatsu-gazou-henkan-wakufuro/\">画像の一括変換ワークフロー</a>をご覧ください。</p>\n<p>フォルダのほとんどがiPhoneの写真なら、<a href=\"/ja/heic-jpg-henkan/\">HEICからJPGへの変換ツール</a>がより速い出発点です。</p>";

export const FAQS: BlogArticleFaq[] = [{"question":"フォルダ全体を一括変換ツールにドラッグできますか？","answer":"はい、できます。フォルダをアップロードエリアにドラッグすれば、ツールが中の画像ファイルを拾います。エリアをクリックして、ファイル選択画面で多くのファイルを一度に選ぶこともできます。どちらの方法でも、有効な画像はすべて同じ変換キューに入ります。"},{"question":"1つの一括バッチに混ぜられるファイル形式は何ですか？","answer":"JPG、PNG、WebP、HEIC、SVG、BMP、GIF、AVIFがすべて同じキューに入ります。有効なファイルはすべて、選んだ出力形式に変換されます。例外はアニメーションGIFだけで、最初のフレームだけが変換されるため静止画になります。"},{"question":"変換後のファイルが原本を上書きしないようにするにはどうすればいいですか？","answer":"-webpや-convertedのような任意のファイル名接尾辞を使ってください。すべての出力が原本と異なる名前になります。さらに、ZIPは原本の上ではなく、新しいフォルダに解凍してください。この2つの習慣を組み合わせれば、上書きは起きません。"},{"question":"バッチ内の1つのファイルだけ変換後に大幅に大きくなったのはなぜですか？","answer":"そのファイルは、おそらく非可逆形式からPNGへ変換されました。PNGはすべての画素を正確に保存するので、数倍大きくなることがあります。あるいは、シンプルな画像なのに画質スライダーを非常に高く設定したのかもしれません。そのファイルのカードを確認し、別の設定で個別に変換することを検討してください。"},{"question":"一括変換を途中で一時停止できますか？","answer":"一時停止ボタンはありません。ただし各ファイルは独立して変換されるので、現在のファイルが終わるのを待って、新しいファイルの追加をやめれば済みます。すでに終わったファイルは、変換済みのままダウンロードできます。再開する場合は、残りのファイルを新しいバッチとしてアップロードしてください。"},{"question":"一括変換ツールはインターネットがなくても使えますか？","answer":"ページが一度読み込まれれば、変換はブラウザ内でローカルに動き、インターネットは不要です。接続が必要なのは、最初にページを開くときだけです。そのあとは、タブを閉じるまでオフラインでバッチを変換できます。"}];
